<div x-data="{}"
    @transaction-receipt.window="$nextTick(() => $refs.receipt?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth',block:'start'}))"
    @return-form-open.window="$nextTick(() => $refs.returnForm?.scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth',block:'start'}))">
    @if($message)<p class="success" role="status">{{ $message }}</p>@endif
    @if($errors->any())<div class="notice" role="alert">@foreach($errors->all() as $error)<p class="error">{{ $error }}</p>@endforeach</div>@endif
    <section class="panel"><div class="section-heading"><div><h2>Transaction history</h2><p class="muted">Completed sales, original receipts, and linked returns in this browser session.</p></div><span class="badge">{{ count($sales) }} matching sales</span></div>
        <div class="form-grid"><label>Find a receipt<input wire:model.live.debounce.250ms="search" placeholder="Receipt number, product, customer or date"></label><label>Payment method<select wire:model.live="method"><option value="">All methods</option><option>Cash</option><option>GCash</option><option>Maya</option><option value="Credit">Grocery credit</option></select></label><label>History period<select wire:model.live="period"><option value="all">All history</option><option value="7">Last 7 days</option><option value="30">Last 30 days</option><option value="90">Last 90 days</option></select></label><label>Sale status<select wire:model.live="status"><option value="">All statuses</option><option>Completed</option><option>Partially returned</option><option>Returned</option></select></label></div>
        <div class="table-wrap"><table><thead><tr><th>Receipt / customer</th><th>Date / time</th><th>Payment</th><th>Original total*</th><th>Status</th><th>Actions</th></tr></thead><tbody>
            @forelse($sales as $sale)<tr wire:key="sale-{{ $sale['id'] }}"><td><strong>{{ $sale['number'] }}</strong>@if($sale['customer'] ?? null)<br><small>{{ $sale['customer'] }}</small>@endif</td><td>{{ \Illuminate\Support\Carbon::parse($sale['time'])->setTimezone('Asia/Shanghai')->format('M j, Y · g:i A') }}</td><td>{{ $sale['method'] === 'Credit' ? 'Grocery credit' : $sale['method'] }}</td><td>{{ number_format($sale['total']/100,2) }}@if($sale['returned'])<br><small>Returned {{ number_format($sale['returned']/100,2) }}<br>Net {{ number_format(($sale['total']-$sale['returned'])/100,2) }}</small>@endif</td><td><span class="status-pill">{{ $sale['returnStatus'] }}</span></td><td><div class="form-actions"><button wire:click="viewReceipt('{{ $sale['id'] }}')">View / Reprint</button>@if($sale['returnStatus'] !== 'Returned')<button wire:click="startReturn('{{ $sale['id'] }}')">Return items</button>@endif</div></td></tr>@empty<tr><td colspan="6">No matching sales in this session.</td></tr>@endforelse
        </tbody></table></div><p class="muted">*Currency and tax settings pending. Reprints preserve the original receipt and do not change stock. Loans and repayments have their own history in Customer Credit & Loans; other money movements are in Shifts & Expenses.</p>
    </section>

    @if($returnSale)<form class="panel" wire:submit="completeReturn" x-ref="returnForm">
        <div class="section-heading"><div><h2>Return items · {{ $returnSale['number'] }}</h2><p class="muted">Use the original sale quantities. One returned pack restores or discards the entire pack.</p></div><span class="badge">{{ $returnSale['method'] === 'Credit' ? 'Grocery credit' : $returnSale['method'] }}</span></div>
        @if(!$cashSession)<p class="notice">Open a cash session before recording a return. <a href="/cash" wire:navigate>Open Shifts & Expenses</a></p>@endif
        @foreach($returnable as $index=>$line)<article class="product" wire:key="return-line-{{ $returnSale['id'] }}-{{ $index }}">
            <h3>{{ $line['name'] }} · {{ $line['label'] }}</h3><p class="muted">Sold {{ $line['quantity'] }} · Returnable {{ $line['remaining'] }} · {{ $line['units'] }} base units each · Original price {{ number_format($line['price']/100,2) }}</p>
            <div class="form-grid"><label>Return quantity · {{ $line['label'] }}<input wire:model.live="returnLines.{{ $index }}.quantity" type="number" min="0" max="{{ $line['remaining'] }}"></label><label>Stock disposition · {{ $line['label'] }}<select wire:model.live="returnLines.{{ $index }}.disposition"><option value="Restock">Sellable · return to stock</option><option value="Discard">Unsellable · discard as loss</option></select></label></div>
        </article>@endforeach
        <label>Reason for return<textarea wire:model="returnReason" rows="2" minlength="3" maxlength="500" placeholder="What was returned and why?" required></textarea></label>
        @if($quote)<div class="notice"><strong>Return value: {{ number_format($quote['total']/100,2) }}</strong><br>Grocery debt reduction: {{ number_format($quote['creditReduction']/100,2) }}<br>Money to refund: {{ number_format($quote['refund']/100,2) }}@if($returnSale['method'] === 'Credit')<br>Reduce the outstanding debt first; refund only the amount that has already been paid.@endif</div>
            @if($quote['refund'] > 0)<label>Refund payment method<select wire:model.live="refundMethod"><option>Cash</option><option>GCash</option><option>Maya</option></select></label><label class="check"><input type="checkbox" wire:model="refundConfirmed"> I have handed or sent the refund to the customer</label><p class="muted">Record a refund you completed yourself. This system does not send GCash or Maya payments.</p>@endif
        @endif
        <p class="muted">Sellable goods increase stock. Discarded goods are recorded as losses without another stock deduction. Returns use original selling prices and saved purchase costs.</p>
        <div class="form-actions"><button class="primary compact" type="submit" wire:loading.attr="disabled" @disabled(!$cashSession || !$quote)>Record return</button><button type="button" wire:click="cancelReturn">Cancel</button></div>
    </form>@endif

    <section class="panel"><h2>Return & refund history</h2><p class="muted">Linked to the original receipt. Search, period and payment filters also apply here.</p>
        <div class="table-wrap"><table><thead><tr><th>Return / receipt</th><th>Recorded</th><th>Return value</th><th>Debt reduction</th><th>Money refunded</th><th>Actions</th></tr></thead><tbody>
            @forelse($returns as $entry)<tr wire:key="return-{{ $entry['id'] }}"><td><strong>{{ $entry['number'] }}</strong><br>{{ $entry['saleNumber'] }}@if($entry['customer'] ?? null)<br><small>{{ $entry['customer'] }}</small>@endif</td><td>{{ \Illuminate\Support\Carbon::parse($entry['time'])->setTimezone('Asia/Shanghai')->format('M j, Y · g:i A') }}</td><td>{{ number_format($entry['total']/100,2) }}</td><td>{{ number_format($entry['creditReduction']/100,2) }}</td><td>{{ number_format($entry['refund']/100,2) }}<br><small>{{ $entry['method'] ?: 'No money refund' }}</small></td><td><button wire:click="viewReturn('{{ $entry['id'] }}')">View return</button></td></tr>@empty<tr><td colspan="6">No matching returns in this session.</td></tr>@endforelse
        </tbody></table></div>
    </section>
    @if($selected)<section class="panel receipt printable-receipt" x-ref="receipt" wire:transition="receipt-preview">@include('components.receipt', ['receipt'=>$selected, 'isCopy'=>true])</section>@endif
    @if($selectedReturn)<section class="panel receipt printable-receipt" x-ref="receipt" wire:transition="receipt-preview">
        <h2>{{ $selectedReturn['shop'] }}</h2><p class="receipt-note">SESSION RETURN · NOT A FISCAL RECEIPT</p><p><strong>{{ $selectedReturn['number'] }}</strong><br>Original receipt: {{ $selectedReturn['saleNumber'] }}<br>{{ \Illuminate\Support\Carbon::parse($selectedReturn['time'])->setTimezone('Asia/Shanghai')->format('M j, Y · g:i A') }}<br>{{ $selectedReturn['operator'] }} · {{ $selectedReturn['counter'] }}</p>
        @foreach($selectedReturn['lines'] as $line)<div class="product"><p class="spread"><span>{{ $line['name'] }}</span><strong>{{ number_format($line['total']/100,2) }}</strong></p><small>{{ $line['label'] }} × {{ $line['quantity'] }} · {{ $line['disposition'] === 'Restock' ? 'Restocked' : 'Discarded' }}</small></div>@endforeach
        <hr><p class="spread"><strong>Return value</strong><strong>{{ number_format($selectedReturn['total']/100,2) }}</strong></p><p>Debt reduced: {{ number_format($selectedReturn['creditReduction']/100,2) }}<br>Money refunded: {{ number_format($selectedReturn['refund']/100,2) }} · {{ $selectedReturn['method'] ?: 'No money refund' }}</p><p>{{ $selectedReturn['reason'] }}</p><p class="muted">Prototype record · Currency and tax settings pending.</p><div class="form-actions no-print"><button type="button" @click="window.print()">Print / Save PDF</button></div>
    </section>@endif
</div>
